// 64 q1_0 rows x 128 cols. Same bytes as 64 block_q1_0, transposed.
// Row-parallel: needs 64 fp32 lanes, i.e. VLEN >= 512.
struct block_q1_0x64 {
    ggml_half d[64];             // per-row scales
    uint8_t   qs[QK1_0][64 / 8]; // 1024 bits/column-group, see q1_0x64_sign_bit
};
static_assert(sizeof(block_q1_0x64) == 64 * sizeof(block_q1_0), "wrong q1_0x64 block size/padding");

// Bit position of row j's sign for column c inside block_q1_0x64::qs, as a flat
// bit index. The repack writer and every gemv/gemm reader go through here, so
// the two supported orders stay consistent by construction.
//
